@JeiPlugin
public class JEIHandler
implements IModPlugin {
    public static final RecipeType<DrillingRecipe> DRILLING = RecipeType.create((String)"createoreexcavation", (String)"drilling", DrillingRecipe.class);
    public static final RecipeType<ExtractorRecipe> EXTRACTING = RecipeType.create((String)"createoreexcavation", (String)"extractor", ExtractorRecipe.class);
    public static final RecipeType<VeinRecipe> VEINS = RecipeType.create((String)"createoreexcavation", (String)"veins", VeinRecipe.class);

    public ResourceLocation getPluginUid() {
        return new ResourceLocation("createoreexcavation", "jei");
    }

    public void registerCategories(IRecipeCategoryRegistration registration) {
        registration.addRecipeCategories(new IRecipeCategory[]{new DrillingCategory(), new ExtractingCategory(), new VeinCategory()});
    }

    public void registerRecipes(IRecipeRegistration registration) {
        RecipeManager mngr = Minecraft.m_91087_().m_91403_().m_105141_();
        registration.addRecipes(DRILLING, mngr.m_44013_(CreateOreExcavation.DRILLING_RECIPES.getRecipeType()));
        registration.addRecipes(EXTRACTING, mngr.m_44013_(CreateOreExcavation.EXTRACTING_RECIPES.getRecipeType()));
        registration.addRecipes(VEINS, mngr.m_44013_(CreateOreExcavation.VEIN_RECIPES.getRecipeType()));
    }

    public void registerRecipeCatalysts(IRecipeCatalystRegistration registration) {
        registration.addRecipeCatalyst(Registration.DRILL_BLOCK.asStack(), new RecipeType[]{DRILLING});
        registration.addRecipeCatalyst(Registration.EXTRACTOR_BLOCK.asStack(), new RecipeType[]{EXTRACTING});
        registration.addRecipeCatalyst(Registration.VEIN_FINDER_ITEM.asStack(), new RecipeType[]{VEINS});
    }

    public void registerIngredients(IModIngredientRegistration registration) {
        new VeinIngredient(registration);
    }
}

